inline fun withLock(block: () -> Unit) {
    print("lock ")
    try {
        block()
    } finally {
        print("unlock ")
    }
}

fun save() {
    withLock {
        print("work ")
        return
    }
    print("after")
}

fun main() {
    save()
}

